"""Review the new source beside installed Branforth directions; no runtime writes."""
from pathlib import Path
import json
import numpy as np

P=Path(__file__).resolve().parent
runtime=P.parent/'crew-runtime-matte-v1/branforth'
m=json.loads((runtime/'manifest.json').read_text())
c=json.loads((P/'checks.json').read_text())
tracks=[]
for direction in ['east','new','south','north']:
    if direction=='new':
        tracks.append(dict(label='East - new larger-head take',files=[f'frames/walk-east/{i:03}.png' for i in range(c['sourceFrames'])],durations=[1000/c['fps']]*c['sourceFrames']))
    else:
        s=next(s for s in m['states'] if s['id']=='walk-'+direction)
        tracks.append(dict(label=direction.title()+' - installed',files=['../crew-runtime-matte-v1/branforth/'+f for f in s['frameFiles']],durations=s['frameDurationsMs']))
b=c['bounds'];h=[x[3]-x[1] for x in b];med=np.array(c['neutralMedians'])
audit=dict(sourceFrames=c['sourceFrames'],fps=c['fps'],firstLastHeight=[h[0],h[-1]],heightRange=[min(h),max(h)],clippedFrames=sum(x[0]<=0 or x[1]<=0 or x[2]>=184 or x[3]>=184 for x in b),neutralMedianRange=[med.min(0).tolist(),med.max(0).tolist()],loopSelected=False,runtimeChanged=False,estimatedUSD=.19,directTotalEstimatedUSD=1.52,actualBillingVerified=False)
(P/'validation.json').write_text(json.dumps(audit,indent=2)+'\n')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Branforth - new east walk</title><style>body{background:#172226;color:#dbe4df;font:17px system-ui;max-width:1150px;margin:24px auto;padding:16px}canvas{display:block;width:100%;height:auto;background:#303b40}img,video{max-width:100%}video{width:min(100%,650px)}button,select,input{font:inherit;padding:6px}a{color:#91d6d1}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center}</style><h1>Branforth - new east walk</h1><p>New direct Hailuo take from the approved larger-head reference. Grey hair, moustache, goggles, muted yellow engineering accents and attached wrench. Existing matte finish and fixed reference registration; no game changes.</p><p>The new take plays the full source at original timing. Installed directions use their current timing. No loop has been selected; the full clip restart is not a finished loop seam.</p><div class="controls"><button id="toggle">Pause</button><label>Speed <select id="speed"><option value="1">Normal</option><option value="0.5">Half</option></select></label><label>Time <input id="phase" type="range" min="0" max="5874" value="0"></label><span id="status">Loading frames...</span></div><h2>Direction comparison</h2><p>Rows: 148px inspection height; approximately 82 / 54 / 27px gameplay sizes.</p><canvas id="board" width="920" height="540"></canvas><h2>Original source video</h2><video src="source.mp4" controls loop muted playsinline preload="metadata"></video><h2>Sampled poses</h2><img src="contact.png"><p>One generation, estimated US$0.19. Higgsfield credits untouched.</p><p><a href="../bill-muted-east-south-v1/">Saved Bill selections</a></p><script>const tracks=TRACKS;let loaded=false,playing=true,t=0,last=0;const canvas=document.getElementById('board'),ctx=canvas.getContext('2d'),phase=document.getElementById('phase'),status=document.getElementById('status');Promise.all(tracks.map(async s=>{s.images=await Promise.all(s.files.map(src=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=()=>reject(src);im.src=src})));s.total=s.durations.reduce((a,b)=>a+b,0)})).then(()=>{loaded=true;status.textContent='All frames loaded'}).catch(e=>status.textContent='Image failed: '+e);document.getElementById('toggle').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause':'Play'};phase.oninput=()=>{t=Number(phase.value);playing=false;document.getElementById('toggle').textContent='Play'};function draw(now){if(last&&playing)t=(t+(now-last)*Number(document.getElementById('speed').value))%5875;last=now;if(loaded){ctx.clearRect(0,0,920,540);ctx.imageSmoothingEnabled=true;tracks.forEach((s,c)=>{let local=t%s.total,i=0;while(i<s.images.length-1&&local>=s.durations[i]){local-=s.durations[i++]}ctx.fillStyle='#dbe4df';ctx.font='13px system-ui';ctx.fillText(s.label,c*230+8,22);[148,82,54,27].forEach((height,row)=>{const side=184*height/148;ctx.drawImage(s.images[i],c*230+(230-side)/2,[38,245,368,457][row],side,side)})});phase.value=Math.floor(t)}requestAnimationFrame(draw)}requestAnimationFrame(draw);</script></html>'''
(P/'index.html').write_text(html.replace('TRACKS',json.dumps(tracks)),encoding='utf-8')
print(json.dumps(audit))
